1	import { describe, it, expect } from "vitest";
2	import { runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office", () => {
5	  // --- Simplest quote cases ---
6	  it("empty item list → premium 5 G (only the processing fee)", () => {
7	    const result = runScenario({
8	      customer: { yearsWithMHPCO: 0 },
9	      steps: [{ op: "quote", items: [] }],
10	    });
11	    expect(result).toEqual({ results: [{ premium: 5 }] });
12	  });
13	
14	  // --- Base premiums for single main items (with first-insurance surcharge always applied) ---
15	  it.todo("single plain sword, newcomer → base 100 + 10 first insurance + 5 fee = 115 G");
16	
17	  // --- Component base premiums ---
18	  it.todo("2 runes → 50 G base premium");
19	  it.todo("3 runes → 60 G base premium (block applies)");
20	  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
21	  it.todo("7 runes → 175 G base premium");
22	
23	  // --- 'Alike' components clarification ---
24	  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
25	  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
26	
27	  // --- Premium modifiers in isolation ---
28	  it.todo("cursed sword adds 50% curse surcharge to item base");
29	  it.todo("sword enchantment 5 adds 30% high-enchantment surcharge");
30	  it.todo("sword enchantment 4 → no high-enchantment surcharge");
31	  it.todo("sword enchantment 5 and cursed → both surcharges apply");
32	  it.todo("customer with exactly 2 years → 20% loyalty discount applies");
33	
34	  // --- Modifier scope on multi-item policies ---
35	  it.todo("cursed sword (100) + plain amulet (60): policy base 160, curse adds 50 → 210 before fee");
36	
37	  // --- Rounding ---
38	  it.todo("premium calculation yielding 197.5 G → 198 G (rounded up)");
39	
40	  // --- Integration examples ---
41	  it.todo("newcomer with cursed sword (steel, ench 3), 0 years, first quote → premium 165 G");
42	  it.todo("long-standing customer's 2nd contract: cursed sword (ench 7), 3 years → premium 160 G");
43	  it.todo("first insurance surcharge applies to each item even on a follow-up contract");
44	
45	  // --- Claim: standard reimbursement ---
46	  it.todo("regular sword (steel, ench 3), damage 500 → payout 400 G (500 - 100 deductible)");
47	  it.todo("rune damage 200 (no ench/material) → payout 100 G (200 - 100 deductible)");
48	
49	  // --- Claim: special clauses ---
50	  it.todo("steel sword ench 9, damage 1000 → payout 400 G (50% then deductible: 500 - 100)");
51	  it.todo("dragon-material sword ench 5, damage 800 → payout 700 G (full then deductible)");
52	  it.todo("dragon-material sword ench 9, damage 1000 → payout 400 G (50% wins: 500 - 100)");
53	  it.todo("dragon-material sword exactly ench 8, damage 1000 → payout 400 G (high-ench then deductible)");
54	
55	  // --- Claim: deductible per damage event ---
56	  it.todo("dragon attack damages sword (500) and amulet (300) → payout 600 G (deductible per item)");
57	
58	  // --- Claim: multiple items of same type ---
59	  it.todo("policy covers two swords → insurance sum 2000, cap 4000; both damaged, separate deductibles");
60	  it.todo("more damage entries of a type than insured → CLI rejects (non-zero exit)");
61	
62	  // --- Claim: cap and insurance sum ---
63	  it.todo("sword + amulet → insurance sum 1600, cap 3200");
64	  it.todo("cursed sword → cap 2000 based on unmodified insurance value");
65	  it.todo("sword + 3 runes → insurance sum 1750 (block discount does not affect insurance sum)");
66	  it.todo("cap exhaustion: two 1500 claims → first payout 1400 (remaining 600), second payout 600 (remaining 0)");
67	
68	  // --- Payout rounding ---
69	  it.todo("payout calculation yielding 350.5 G → payout 350 G (rounded down)");
70	
71	  // --- Error cases ---
72	  it.todo("quote with unknown item type → throws / non-zero exit, no results");
73	  it.todo("claim referencing an item not in the policy → throws / non-zero exit");
74	  it.todo("claim damage entry with negative amount → throws / non-zero exit");
75	});
